    Uri.parse('$base/api/networks/$networkId/join'),
    headers: {'content-type': 'application/json'},
    body: jsonEncode({
      'password': [REDACTED:Sensitive Value],
      'displayName': 'fa-probe (invite test)',
    }),
  );
