          base64Decode(channelKeys['pub'] as String),
          type: KeyPairType.x25519));
  final ikm = await shared.extractBytes();
  final key = await _hkdf(
      ikm: ikm,
      salt: utf8.encode(frameId),
      info: utf8.encode('dap1/v1'),
      length: 32);
