      Uint8List.fromList(List.generate(12, (_) => _rng.nextInt(256)));
  final box = await _aead.encrypt(utf8.encode(text),
      secretKey: SecretKey(key),
      nonce: nonce,
      aad: utf8.encode('dap1|$frameId|$channelName'));
