    1, ...senderPub.bytes, ...nonce, ...box.cipherText, ...box.mac.bytes,
  ]);

  // 4. Relay-accept.
  final sent = await http.post(
    Uri.parse('$base/api/channels/$channelId/messages'),
    headers: auth,
    body: jsonEncode({
      'id': frameId,
      'payload': payload,
